package vn.vinhkhang.warehouse;
import java.util.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
@RestController @RequestMapping("/api/database-reset")
public class DatabaseReset {
 private final Map<Long,long[]> failures=new HashMap<>();
 private void verifyPassword(long user,String password,String hash){long now=System.currentTimeMillis();long[] attempt=failures.get(user);if(attempt!=null&&attempt[0]>=5&&now<attempt[1])throw problem(429,"Nhập sai mật khẩu nhiều lần. Anh thử lại sau 5 phút.");if(!new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder().matches(password,hash)){long count=attempt==null||now>=attempt[1]?1:attempt[0]+1;failures.put(user,new long[]{count,now+300000});throw problem(400,"Mật khẩu Admin không đúng");}failures.remove(user);}
 private final Api core;private final JdbcTemplate db;private final TransactionTemplate tx;
 private final FinanceSnapshot snapshot;
 public DatabaseReset(Api core,JdbcTemplate db,PlatformTransactionManager manager,FinanceSnapshot snapshot){this.core=core;this.db=db;tx=new TransactionTemplate(manager);this.snapshot=snapshot;group("transactions","Giao dịch, nhập xuất, sản xuất, xe, doanh số và tồn kho","sales_transfers,revenue_entries,revenue_lines,revenue_sales,vehicle_shipment_lines,vehicle_shipments,stock_movements,production_line_materials,production_materials,vehicles,vehicle_receipts,production_order_lines,production_orders,stock_document_lines,stock_documents,retained_stock_effects,stock_balances");group("parts","Danh mục linh kiện và phân nhóm","part_color_models,parts");group("models","Mẫu xe","vehicle_models");group("bom","Định mức BOM","bom_lines,bom_versions");group("suppliers","Nhà cung cấp","suppliers");group("dealers","Các đại lý","dealers");group("carriers","Nhà xe vận chuyển","carriers");group("users","Tài khoản và mã khôi phục","recovery_secrets,app_users");group("trash","Các mục đã xóa","deleted_records");group("audit","Nhật ký hoạt động","audit_log");}
 private Api.Problem problem(int status,String message){return new Api.Problem(status,message);}
 @ExceptionHandler(Api.Problem.class) public org.springframework.http.ResponseEntity<?> fail(Api.Problem e){return org.springframework.http.ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
 
 private final LinkedHashMap<String,List<String>> groups=new LinkedHashMap<>();
 private final LinkedHashMap<String,String> labels=new LinkedHashMap<>();
 private void group(String key,String label,String tables){groups.put(key,List.of(tables.split(",")));labels.put(key,label);}
 private Set<String> all(){Set<String>s=new LinkedHashSet<>();groups.values().forEach(s::addAll);return s;}
 private Map<String,Set<String>> dependencies(){return db.execute((org.springframework.jdbc.core.ConnectionCallback<Map<String,Set<String>>>)c->{var out=new LinkedHashMap<String,Set<String>>();for(String child:all()){var parents=new HashSet<String>();try(var rs=c.getMetaData().getImportedKeys(null,"PUBLIC",child.toUpperCase(Locale.ROOT))){while(rs.next()){String p=rs.getString("PKTABLE_NAME").toLowerCase(Locale.ROOT);if(!p.equals(child)&&all().contains(p))parents.add(p);}} out.put(child,parents);}return out;});}
 private Set<String> plan(Map<String,Object>b){Object raw=b.get("groups");if(!(raw instanceof List<?> list)||list.isEmpty())throw problem(400,"Chọn ít nhất một mục cần xóa");var out=new LinkedHashSet<String>();for(Object key:list){var tables=groups.get(key.toString());if(tables==null)throw problem(400,"Mục xóa không hợp lệ");out.addAll(tables);}var deps=dependencies();boolean changed;do{int size=out.size();for(var e:deps.entrySet())if(e.getValue().stream().anyMatch(out::contains))out.add(e.getKey());if(out.stream().anyMatch(groups.get("transactions")::contains))out.addAll(groups.get("transactions"));if(out.stream().anyMatch(groups.get("transactions")::contains)||out.contains("parts")||out.contains("vehicle_models")){out.add("deleted_records");out.add("audit_log");} changed=out.size()!=size;}while(changed);return out;}
 private List<String> order(Set<String> tables){var deps=dependencies();var left=new LinkedHashSet<>(tables);var ordered=new ArrayList<String>();while(!left.isEmpty()){String next=left.stream().filter(parent->left.stream().noneMatch(child->!child.equals(parent)&&deps.get(child).contains(parent))).findFirst().orElseThrow(()->problem(400,"Không thể xác định thứ tự xóa dữ liệu liên quan"));ordered.add(next);left.remove(next);}return ordered;}
 private String primaryOrder(String table){return db.execute((org.springframework.jdbc.core.ConnectionCallback<String>)c->{var columns=new TreeMap<Integer,String>();try(var rs=c.getMetaData().getPrimaryKeys(null,"PUBLIC",table.toUpperCase(Locale.ROOT))){while(rs.next())columns.put(rs.getInt("KEY_SEQ"),rs.getString("COLUMN_NAME"));}return columns.isEmpty()?"":" ORDER BY "+String.join(",",columns.values());});}
 private String fingerprint(Set<String> tables){try{var digest=java.security.MessageDigest.getInstance("SHA-256");for(String table:new TreeSet<>(tables)){digest.update(table.getBytes(java.nio.charset.StandardCharsets.UTF_8));db.query("SELECT * FROM "+table+primaryOrder(table),(org.springframework.jdbc.core.RowCallbackHandler)rs->{try{var row=new java.io.ByteArrayOutputStream();var data=new java.io.DataOutputStream(row);for(int i=1;i<=rs.getMetaData().getColumnCount();i++){Object value=rs.getObject(i);byte[] bytes=value==null?new byte[0]:value instanceof byte[] a?a:rs.getString(i).getBytes(java.nio.charset.StandardCharsets.UTF_8);data.writeBoolean(value!=null);data.writeInt(bytes.length);data.write(bytes);}digest.update(row.toByteArray());}catch(java.io.IOException e){throw new IllegalStateException(e);}});}return java.util.HexFormat.of().formatHex(digest.digest());}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private Map<String,Object> describe(Set<String> tables){var rows=new ArrayList<Map<String,Object>>();for(var e:groups.entrySet()){long count=0;var included=new ArrayList<String>();for(String table:e.getValue())if(tables.contains(table)){count+=db.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);included.add(table);}if(!included.isEmpty())rows.add(Map.of("label",labels.get(e.getKey()),"count",count,"tables",included));}return Map.of("affected",rows,"fingerprint",fingerprint(tables),"accounts",tables.contains("app_users"));}

 @GetMapping public synchronized Object catalog(@RequestHeader(value="Authorization",required=false) String token){core.admin(token);return groups.entrySet().stream().map(e->Map.of("key",e.getKey(),"label",labels.get(e.getKey()))).toList();}
 @PostMapping("/preview") public synchronized Object preview(@RequestHeader(value="Authorization",required=false) String token,@RequestBody Map<String,Object>body){core.admin(token);return describe(plan(body));}
 @PostMapping("/execute") public synchronized Object execute(@RequestHeader(value="Authorization",required=false) String token,@RequestBody Map<String,Object>body)throws Exception{var user=core.admin(token);String hash=db.queryForObject("SELECT password_hash FROM app_users WHERE id=?",String.class,user.id());
 verifyPassword(user.id(),Objects.toString(body.get("password"),""),hash);
 if(Objects.toString(body.get("reason"),"").trim().isEmpty()||Objects.toString(body.get("reason"),"").length()>400)throw problem(400,"Nhập lý do xóa, tối đa 400 ký tự");
 if(!"XOA DU LIEU".equals(body.get("confirmation")))throw problem(400,"Nhập XOA DU LIEU để xác nhận");
 var tables=plan(body);if(!fingerprint(tables).equals(body.get("fingerprint")))throw problem(409,"Dữ liệu đã thay đổi. Anh xem lại danh sách trước khi xóa.");var backup=core.backup(token);try(var zip=new java.util.zip.ZipFile(backup.get("file"))){if(zip.size()==0)throw new java.io.IOException();}tx.executeWithoutResult(t->{if(tables.contains("stock_documents"))db.update("UPDATE stock_documents SET return_source_id=NULL");for(String table:order(tables))db.update("DELETE FROM "+table);if(tables.contains("app_users"))db.update("UPDATE app_setup_state SET completed=FALSE WHERE id=1");else core.audit(user,"RESET_SELECTED_DATA","database",0);});snapshot.publish();return Map.of("ok",true,"backup",backup.get("file"),"accounts",tables.contains("app_users"));
 }
}
